theorem ProbabilityTheory.IndepFun.extracted_1.{u_3, u_2, u_1} {Ω : Type u_1} {α : Type u_2} {β : Type u_3}
  {x : MeasurableSpace Ω} {x_1 : MeasurableSpace α} {x_2 : MeasurableSpace β} {μ : Measure Ω} {A : Ω → α} {B : Ω → β}
  (hi : IndepFun A B μ) {s : Set α} (hs : MeasurableSet s) (hA : Measurable A) (u : Set α) (v : Set β)
  (hu : MeasurableSet u) (hv : MeasurableSet v) : A ⁻¹' s ∩ (A ⁻¹' u ∩ B ⁻¹' v) = A ⁻¹' (s ∩ u) ∩ B ⁻¹' v := by
  aesop

theorem ProbabilityTheory.IndepFun.extracted_1.{u_3, u_2, u_1} {Ω : Type u_1} {α : Type u_2} {β : Type u_3}
  {x : MeasurableSpace Ω} {x_1 : MeasurableSpace α} {x_2 : MeasurableSpace β} {μ : Measure Ω} {A : Ω → α} {B : Ω → β}
  (hi : IndepFun A B μ) {s : Set α} {t : Set β} (hs : MeasurableSet s) (ht : MeasurableSet t) (hA : Measurable A)
  (hB : Measurable B) (u : Set α) (v : Set β) (hu : MeasurableSet u) (hv : MeasurableSet v) :
  A ⁻¹' s ∩ B ⁻¹' t ∩ (A ⁻¹' u ∩ B ⁻¹' v) = A ⁻¹' (s ∩ u) ∩ B ⁻¹' (t ∩ v) := by
  aesop
